try:
    data = json.loads(text)
except (ValueError, TypeError):
    raise ValueError('invalid JSON')

if not isinstance(data, dict):
    raise ValueError('manifest must be an object')

bundle_id = data.get('bundle_id')
if not isinstance(bundle_id, str) or isinstance(bundle_id, bool) or not bundle_id:
    raise ValueError('bundle_id must be a nonempty string')

files = data.get('files')
if not isinstance(files, list) or isinstance(files, bool):
    raise ValueError('files must be a list')

total_bytes = 0
for entry in files:
    if not isinstance(entry, dict):
        raise ValueError('each file must be an object')
    path = entry.get('path')
    if not isinstance(path, str) or isinstance(path, bool) or not path:
        raise ValueError('path must be a nonempty string')
    size_bytes = entry.get('size_bytes')
    if not isinstance(size_bytes, int) or isinstance(size_bytes, bool) or size_bytes < 0:
        raise ValueError('size_bytes must be a nonnegative integer')
    total_bytes += size_bytes

return {'bundle_id': bundle_id, 'file_count': len(files), 'total_bytes': total_bytes}
